var toggle = document.getElementById('sort-toggle')
var list = document.getElementById('sort-list')
var label = document.getElementById('sort-label')
var options = Array.prototype.slice.call(document.querySelectorAll('.dd-option'))

function openDropdown() {
  list.classList.add('open')
  toggle.setAttribute('aria-expanded', 'true')
}

function closeDropdown() {
  list.classList.remove('open')
  toggle.setAttribute('aria-expanded', 'false')
}

function isDropdownOpen() {
  return toggle.getAttribute('aria-expanded') === 'true'
}

function setOptionFocus(option) {
  options.forEach(function (opt) {
    opt.setAttribute('tabindex', '-1')
  })
  option.setAttribute('tabindex', '0')
  option.focus()
}

toggle.addEventListener('click', function () {
  if (isDropdownOpen()) {
    closeDropdown()
  } else {
    openDropdown()
    setTimeout(function () {
      if (options.length > 0) {
        setOptionFocus(options[0])
      }
    }, 0)
  }
})

toggle.addEventListener('keydown', function (e) {
  if (e.key === 'Enter' || e.key === ' ') {
    e.preventDefault()
    if (isDropdownOpen()) {
      closeDropdown()
    } else {
      openDropdown()
      setTimeout(function () {
        if (options.length > 0) {
          setOptionFocus(options[0])
        }
      }, 0)
    }
  } else if (e.key === 'ArrowDown') {
    e.preventDefault()
    if (!isDropdownOpen()) {
      openDropdown()
    }
    setTimeout(function () {
      if (options.length > 0) {
        setOptionFocus(options[0])
      }
    }, 0)
  } else if (e.key === 'ArrowUp') {
    e.preventDefault()
    if (!isDropdownOpen()) {
      openDropdown()
    }
    setTimeout(function () {
      if (options.length > 0) {
        setOptionFocus(options[options.length - 1])
      }
    }, 0)
  } else if (e.key === 'Escape') {
    closeDropdown()
    toggle.focus()
  }
})

options.forEach(function (option) {
  option.addEventListener('click', function () {
    label.textContent = 'Sort: ' + option.getAttribute('data-value')
    closeDropdown()
    toggle.focus()
  })

  option.addEventListener('keydown', function (e) {
    var currentIndex = options.indexOf(option)
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault()
      label.textContent = 'Sort: ' + option.getAttribute('data-value')
      closeDropdown()
      toggle.focus()
    } else if (e.key === 'ArrowDown') {
      e.preventDefault()
      if (currentIndex < options.length - 1) {
        setOptionFocus(options[currentIndex + 1])
      } else {
        setOptionFocus(options[0])
      }
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      if (currentIndex > 0) {
        setOptionFocus(options[currentIndex - 1])
      } else {
        setOptionFocus(options[options.length - 1])
      }
    } else if (e.key === 'Home') {
      e.preventDefault()
      setOptionFocus(options[0])
    } else if (e.key === 'End') {
      e.preventDefault()
      setOptionFocus(options[options.length - 1])
    } else if (e.key === 'Escape') {
      e.preventDefault()
      closeDropdown()
      toggle.focus()
    }
  })
})

